import api from "./api";

export interface PaymentRequest {
    orderId: string;
    description: string;
}

/**
 * Response returned when initiating a QR payment.
 *
 * qrString MUST be the actual payment-provider QR payload,
 * not a URL generated by the frontend.
 */
export interface PaymentResponse {
    transaction_uuid: string;
    amount: string;
    qrString: string;
    status: "PENDING" | "COMPLETE" | "FAILED";
}

export interface VerifyPaymentResponse {
    transaction_uuid: string;
    amount: string;
    status: "PENDING" | "COMPLETE" | "FAILED";
}

export interface ApiResponse<T> {
    success: boolean;
    message: string;
    data: T;
    status: number;
    errors: any;
    timestamp: string;
}

export const initiateEsewaPaymentApi = async (
    tenantSlug: string,
    payload: PaymentRequest
): Promise<ApiResponse<PaymentResponse>> => {
    const response = await api.post<ApiResponse<PaymentResponse>>(
        `/public/${tenantSlug}/users/payments/esewa/initiate`,
        payload
    );

    return response.data;
};

export const verifyEsewaPaymentApi = async (
    tenantSlug: string,
    transactionUuid: string
): Promise<ApiResponse<VerifyPaymentResponse>> => {
    const response = await api.get<ApiResponse<VerifyPaymentResponse>>(
        `/public/${tenantSlug}/users/payments/esewa/verify`,
        {
            params: {
                transaction_uuid: transactionUuid,
            },
        }
    );

    return response.data;
};